-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     TRUNC(SYSDATE)                                        AS \"Report Date\",      oh.ORDER_NO                                           AS \"PO Number\",     oh.STATUS                                             AS \"PO Status Code\",     CASE oh.STATUS         WHEN 'W' THEN 'Worksheet'         WHEN 'S' THEN 'Submitted'         WHEN 'A' THEN 'Approved'         WHEN 'C' THEN 'Closed'         ELSE oh.STATUS     END                                                   AS \"PO Status Description\",     oh.WRITTEN_DATE                                       AS \"PO Written Date\",     oh.NOT_BEFORE_DATE                                    AS \"Not Before Date\",     oh.NOT_AFTER_DATE                                     AS \"Not After Date\",     oh.CURRENCY_CODE                                      AS \"PO Currency\",     oh.TERMS                                              AS \"Payment Terms\",      oh.SUPPLIER                                           AS \"Supplier ID\",     sp.SUP_NAME                                           AS \"Supplier Name\",     sp.SUP_STATUS                                         AS \"Supplier Status\",      ol.LOCATION                                           AS \"Warehouse ID\",     wh.WH_NAME                                            AS \"Warehouse Name\",     wh.STOCKHOLDING_IND                                   AS \"Stockholding Indicator\",      im.DEPT                                               AS \"Department Number\",     d.DEPT_NAME                                           AS \"Department Name\",     im.CLASS                                              AS \"Class Number\",     c.CLASS_NAME                                          AS \"Class Name\",     im.SUBCLASS                                           AS \"Subclass Number\",     sc.SUB_NAME                                           AS \"Subclass Name\",      ol.ITEM                                               AS \"Item ID\",     im.ITEM_DESC                                          AS \"Item Description\",     im.STANDARD_UOM                                       AS \"Unit of Measure\",     im.PACK_IND                                           AS \"Pack Indicator\",      ol.QTY_ORDERED                                        AS \"Quantity Ordered\",     ol.QTY_RECEIVED                                       AS \"Quantity Received\",     NVL(ol.QTY_ORDERED, 0) - NVL(ol.QTY_RECEIVED, 0)    AS \"Quantity Outstanding\",      ol.UNIT_COST                                          AS \"Gross Unit Cost\",     ROUND(ol.QTY_ORDERED * ol.UNIT_COST, 4)              AS \"Gross Total Cost\",      odd.DEAL_ID                                           AS \"Deal ID\",     odd.DEAL_DETAIL_ID                                    AS \"Deal Detail ID\",      dh.BILLING_TYPE                                       AS \"Billing Type Code\",     CASE dh.BILLING_TYPE         WHEN 'OI'  THEN 'Off Invoice (Guaranteed - Net Cost)'         WHEN 'BB'  THEN 'Bill Back (Non-Guaranteed - Net-Net Cost)'         WHEN 'BBR' THEN 'Bill Back Rebate (Non-Guaranteed - Dead Net)'         WHEN 'VFP' THEN 'Vendor Funded Promotion (Non-Guaranteed - Dead Net)'         WHEN 'VFM' THEN 'Vendor Funded Markdown (Non-Guaranteed - Dead Net)'         ELSE dh.BILLING_TYPE     END                                                   AS \"Billing Type Description\",      CASE dh.BILLING_TYPE         WHEN 'BB'  THEN 'NON-GUARANTEED - Bill Back Accrual'         WHEN 'BBR' THEN 'NON-GUARANTEED - Bill Back Rebate Accrual'         WHEN 'VFP' THEN 'NON-GUARANTEED - Vendor Funded Promotion'         WHEN 'VFM' THEN 'NON-GUARANTEED - Vendor Funded Markdown'         ELSE 'OTHER'     END                                                   AS \"Discount Category\",      odd.DISCOUNT_TYPE                                     AS \"Discount Type Code\",     CASE odd.DISCOUNT_TYPE         WHEN 'P' THEN 'Percentage'         WHEN 'A' THEN 'Fixed Amount'         WHEN 'F' THEN 'Free Goods'         ELSE odd.DISCOUNT_TYPE     END                                                   AS \"Discount Type Description\",     odd.DISCOUNT_VALUE                                    AS \"Discount Value\",     odd.DISCOUNT_AMT_PER_UNIT                             AS \"Discount Amount Per Unit\",      ROUND(NVL(odd.DISCOUNT_AMT_PER_UNIT, 0)           * NVL(ol.QTY_ORDERED, 0), 4)                   AS \"Discount Amount\",     odd.LAST_CALC_DATE                                    AS \"Discount Last Calculated Date\",     odd.PAID_IND                                          AS \"Discount Paid Indicator\",      CASE         WHEN ROUND(ol.QTY_ORDERED * ol.UNIT_COST, 4) &gt; 0         THEN ROUND(              (NVL(odd.DISCOUNT_AMT_PER_UNIT, 0) * NVL(ol.QTY_ORDERED, 0))              / (ol.QTY_ORDERED * ol.UNIT_COST) * 100, 2)     END                                                   AS \"Discount Percent of Gross\",      ROUND(NVL(ol.QTY_ORDERED, 0) * NVL(ol.UNIT_COST, 0)           - (NVL(odd.DISCOUNT_AMT_PER_UNIT, 0) * NVL(ol.QTY_ORDERED, 0)), 4)                                                           AS \"Net Cost After Discount\",      dh.COMMENTS                                           AS \"Deal Description\",     dh.TYPE                                               AS \"Deal Type Code\",     CASE dh.TYPE         WHEN 'A' THEN 'Annual Deal'         WHEN 'P' THEN 'Promotional Deal'         WHEN 'O' THEN 'PO Specific Deal'         WHEN 'M' THEN 'Vendor Funded Markdown'     END                                                   AS \"Deal Type Description\",     dh.STATUS                                             AS \"Deal Status\",     dh.ACTIVE_DATE                                        AS \"Deal Active Date\",     dh.CLOSE_DATE                                         AS \"Deal Close Date\",     dh.SUPPLIER                                           AS \"Deal Vendor ID\",     dh.CURRENCY_CODE                                      AS \"Deal Currency\",     dh.EXT_REF_NO                                         AS \"Deal External Reference Number\",      dd.COST_APPL_IND                                      AS \"Cost Application Type\",     dd.DEAL_CLASS                                         AS \"Deal Class Code\",     CASE dd.DEAL_CLASS         WHEN 'CU' THEN 'Cumulative'         WHEN 'CA' THEN 'Cascade'         WHEN 'EX' THEN 'Exclusive'     END                                                   AS \"Deal Class Description\",     dd.DEAL_COMP_TYPE                                     AS \"Deal Component Type\",     dd.TRAN_DISCOUNT_IND                                  AS \"Transaction Discount Indicator\",      ohd.TOTAL_DISCOUNT_AMT                                AS \"Order Level Discount Amount\",      CASE         WHEN dh.BILLING_TYPE IN ('BB','BBR')         THEN 'ACCRUED - Bill Back income will be invoiced by supplier'         WHEN dh.BILLING_TYPE IN ('VFP','VFM')         THEN 'ACCRUED - Vendor will fund via promotional income'         ELSE 'REVIEW'     END                                                   AS \"Income Recognition Note\"  FROM    MFCS_RDS.RDS_WV_ORDHEAD                    oh     JOIN  MFCS_RDS.RDS_WV_ORDLOC              ol    ON  oh.ORDER_NO    = ol.ORDER_NO                                                     AND ol.LOC_TYPE   = 'W'     JOIN  MFCS_RDS.RDS_WV_ORDLOC_DISCOUNT    odd    ON  ol.ORDER_NO    = odd.ORDER_NO                                                     AND ol.ITEM        = odd.ITEM                                                     AND ol.LOCATION    = odd.LOCATION     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER         im    ON  ol.ITEM        = im.ITEM    JOIN  MFCS_RDS.RDS_WV_DEPS                d     ON  im.DEPT        = d.DEPT    JOIN  MFCS_RDS.RDS_WV_CLASS               c     ON  im.DEPT        = c.DEPT                                                     AND im.CLASS       = c.CLASS    JOIN  MFCS_RDS.RDS_WV_SUBCLASS            sc    ON  im.DEPT        = sc.DEPT                                                     AND im.CLASS       = sc.CLASS                                                     AND im.SUBCLASS    = sc.SUBCLASS     JOIN  MFCS_RDS.RDS_WV_WH                  wh    ON  ol.LOCATION    = wh.WH     LEFT JOIN MFCS_RDS.RDS_WV_SUPS            sp    ON  oh.SUPPLIER    = sp.SUPPLIER     LEFT JOIN MFCS_RDS.RDS_WV_DEAL_HEAD       dh    ON  odd.DEAL_ID    = dh.DEAL_ID                                                     AND dh.BILLING_TYPE IN ('BB','BBR','VFP','VFM')     LEFT JOIN MFCS_RDS.RDS_WV_DEAL_DETAIL     dd    ON  odd.DEAL_ID       = dd.DEAL_ID                                                     AND odd.DEAL_DETAIL_ID = dd.DEAL_DETAIL_ID     LEFT JOIN MFCS_RDS.RDS_WV_ORDHEAD_DISCOUNT ohd  ON  oh.ORDER_NO    = ohd.ORDER_NO                                                     AND ohd.DEAL_ID    = odd.DEAL_ID WHERE    ol.LOC_TYPE = 'W'    AND dh.BILLING_TYPE IN ('BB','BBR','VFP','VFM')    AND oh.WRITTEN_DATE &gt;= ADD_MONTHS(SYSDATE, -3) ORDER BY    ROUND(NVL(odd.DISCOUNT_AMT_PER_UNIT, 0)          * NVL(ol.QTY_ORDERED, 0), 4)                   DESC,    oh.WRITTEN_DATE                                       DESC,    sp.SUP_NAME,    oh.ORDER_NO,    ol.ITEM</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>Report Date</ds:name><ds:datatype>timestamp</ds:datatype></ds:column><ds:column><ds:name>PO Number</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>PO Status Code</ds:name><ds:datatype>varchar(1)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>PO Status Description</ds:name><ds:datatype>varchar(9)</ds:datatype></ds:column><ds:column><ds:name>PO Written Date</ds:name><ds:datatype>timestamp</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Not Before Date</ds:name><ds:datatype>timestamp</ds:datatype></ds:column><ds:column><ds:name>Not After Date</ds:name><ds:datatype>timestamp</ds:datatype></ds:column><ds